mesSim(document.getElementById("sim-l36"),Object.assign({id:"l36"},{kind:"api",title:"Ghép chuỗi SQL và truy vấn tham số",sub:"Hai endpoint cùng tra một máy trong PostgreSQL thu nhỏ. /unsafe ghép chuỗi; /machines dùng tham số %s.",store:{},
 routes:[{m:"GET",p:"/unsafe/machines/{id}",d:"ghép chuỗi (SAI)",h:({params})=>{const db=MSQL.DB([{name:"machine",cols:[{n:"machine_id",ty:"text",pk:1},{n:"name",ty:"text"}],rows:[{machine_id:"L1-M1",name:"Máy rót"},{machine_id:"L1-M2",name:"Máy dán nắp"},{machine_id:"L1-M3",name:"Máy cân"}]}]);
    const id=decodeURIComponent(params.id);const sql="SELECT * FROM machine WHERE machine_id = '"+id+"'";const r=db.exec(sql).pop();return r.err?{status:500,body:{sql,error:r.err}}:{status:200,body:{sql,rows:r.rows}}}},
  {m:"GET",p:"/machines/{id}",d:"tham số (ĐÚNG)",h:({params})=>{const id=decodeURIComponent(params.id);const rows=[["L1-M1","Máy rót"],["L1-M2","Máy dán nắp"],["L1-M3","Máy cân"]].filter(r=>r[0]===id);
    return rows.length?{status:200,body:{sql:"SELECT * FROM machine WHERE machine_id = %s",params:[id],rows}}:{status:404,body:{sql:"SELECT * FROM machine WHERE machine_id = %s",params:[id],detail:"Không có máy"}}}}],
 path:"/unsafe/machines/L1-M1",samples:[{l:"Chuỗi tấn công",m:"GET",p:"/unsafe/machines/x' OR '1'='1"},{l:"Cùng chuỗi, có tham số",m:"GET",p:"/machines/x' OR '1'='1"}],
 tasks:[{t:"Tra L1-M1 qua /unsafe: đọc câu SQL máy chủ đã ghép.",check:(s,c)=>c.has("http",e=>/unsafe/.test(e.path)&&e.status===200&&e.body.rows&&e.body.rows.length===1)},
  {t:"Gửi chuỗi <code>x' OR '1'='1</code> qua /unsafe.",ok:"Điều kiện thành luôn đúng: trả cả ba máy. Kẻ gửi đã đổi nghĩa câu SQL.",check:(s,c)=>c.has("http",e=>/unsafe/.test(e.path)&&e.body.rows&&e.body.rows.length===3)},
  {t:"Gửi đúng chuỗi đó qua endpoint dùng tham số.",ok:"404: chuỗi được tìm nguyên văn như một mã máy, không đổi được câu lệnh.",check:(s,c)=>c.has("http",e=>!/unsafe/.test(e.path)&&/OR/.test(decodeURIComponent(e.path))&&e.status===404)}]}));

